import pygments
from pygments.lexers import get_lexer_by_name, get_lexer_for_filename, guess_lexer, ClassNotFound
from pygments.formatters import Terminal256Formatter, TerminalTrueColorFormatter, TerminalFormatter

from data import LANGUAGES_LIST, THEMES_LIST
from completions_data import COMPLETIONS
from ack_data import ACKNOWLEDGEMENTS

VERSION_STRING = "bat 0.26.1 (4dd824a)\n"

# Load help files
SHORT_HELP_PATH = os.path.join(os.path.dirname(__file__), '..', 'doc', 'short-help.txt')
LONG_HELP_PATH = os.path.join(os.path.dirname(__file__), '..', 'doc', 'long-help.txt')

if os.path.exists(SHORT_HELP_PATH):
