        LONG_HELP = f.read() + "\nYou can use 'bat cache' to customize syntaxes and themes. See 'bat cache --help' for more\ninformation\n"
else:
    LONG_HELP = SHORT_HELP

CACHE_HELP = """Modify the syntax-definition and theme cache

Usage: executable cache [OPTIONS]

Options:
  -h, --help
          Print help

  -b, --build
          Initialize (or update) the syntax/theme cache by loading from the source directory
          (default: the configuration directory).

  -c, --clear
          Remove the cached syntax definitions and themes.

