    'zenburn': 'zenburn',
}

def get_config_file_path():
    if 'BAT_CONFIG_PATH' in os.environ:
        return os.environ['BAT_CONFIG_PATH']
    if 'XDG_CONFIG_HOME' in os.environ:
        return os.path.join(os.environ['XDG_CONFIG_HOME'], 'bat', 'config')
    return os.path.expanduser('~/.config/bat/config')

def get_config_dir_path():
    cfg_file = get_config_file_path()
    return os.path.dirname(cfg_file)

def get_cache_dir_path():
    if 'BAT_CACHE_PATH' in os.environ:
        return os.environ['BAT_CACHE_PATH']
    if 'XDG_CACHE_HOME' in os.environ:
        return os.path.join(os.environ['XDG_CACHE_HOME'], 'bat')
    return os.path.expanduser('~/.cache/bat')

def load_config_args(config_path):
    if not os.path.isfile(config_path):
        return []
    args = []
    try:
        with open(config_path, 'r', encoding='utf-8', errors='replace') as f:
            for line in f:
                line = line.strip()
                if not line or line.startswith('#'):
                    continue
                args.extend(shlex.split(line))
    except Exception:
        pass
    return args

def format_file_size(size_bytes):
    if size_bytes < 1024:
        return f"{size_bytes} B"
    elif size_bytes < 1024 * 1024:
        val = round(size_bytes / 1024.0, 1)
        return f"{val} KiB"
    elif size_bytes < 1024 * 1024 * 1024:
        val = round(size_bytes / (1024.0 * 1024.0), 1)
        return f"{val} MiB"
    else:
        val = round(size_bytes / (1024.0 * 1024.0 * 1024.0), 1)
        return f"{val} GiB"

def parse_line_range_spec(spec):
    # Parses specs like 30:40, :40, 40:, 40, -10:, 30:+10, 35::5, 30:40:2
    spec = spec.strip()
    if spec.startswith('-') and spec.endswith(':'):
        # -N: (last N lines)
        try:
            n = int(spec[:-1])
            return ('last', abs(n))
        except ValueError:
            pass
    parts = spec.split(':')
    if len(parts) == 1:
        # single line
        try:
            val = int(parts[0])
            return (val, val)
        except ValueError:
            return (1, sys.maxsize)
    elif len(parts) == 2:
        p1, p2 = parts[0], parts[1]
        start = int(p1) if p1 else 1
        if p2.startswith('+'):
            end = start + int(p2[1:])
        else:
            end = int(p2) if p2 else sys.maxsize
        return (start, end)
    elif len(parts) == 3:
        p1, p2, p3 = parts[0], parts[1], parts[2]
        if p1 and p2 == '' and p3:
            # A::N -> A-N through A+N
            center = int(p1)
            ctx = int(p3)
            return (max(1, center - ctx), center + ctx)
        elif p1 and p2 and p3:
            # A:B:C -> A-C through B+C
            start = int(p1)
            end = int(p2)
            ctx = int(p3)
            return (max(1, start - ctx), end + ctx)
    return (1, sys.maxsize)

def parse_style_arg(style_str, current_styles):
    items = [s.strip() for s in style_str.split(',') if s.strip()]
    if not items:
        return current_styles

    all_mods = all(item.startswith('+') or item.startswith('-') for item in items)

    if not all_mods:
        current_set = set()
    else:
        current_set = set(current_styles)

    for item in items:
        action = 'add'
        if item.startswith('+'):
            comp = item[1:]
        elif item.startswith('-'):
            action = 'remove'
            comp = item[1:]
        else:
            comp = item

        # Resolve aliases
        comps = []
        if comp in ('default', 'auto'):
            comps = ['changes', 'grid', 'header-filename', 'numbers', 'snip']
        elif comp == 'full':
            comps = ['changes', 'grid', 'header-filename', 'header-filesize', 'numbers', 'snip', 'rule']
        elif comp == 'plain':
            comps = []
            if action == 'add' and not all_mods:
                current_set.clear()
        elif comp == 'header':
            comps = ['header-filename']
        elif comp in ('changes', 'grid', 'header-filename', 'header-filesize', 'numbers', 'snip', 'rule'):
            comps = [comp]

        for c in comps:
            if action == 'add':
                current_set.add(c)
            else:
                current_set.discard(c)

    # Maintain deterministic order
    order = ['changes', 'grid', 'header-filename', 'header-filesize', 'numbers', 'snip', 'rule']
    return [c for c in order if c in current_set]

def get_git_changes(filepath):
    if not filepath or filepath == '-':
        return {}
    if not os.path.exists(filepath):
        return {}
    dirname = os.path.dirname(os.path.abspath(filepath))
    basename = os.path.basename(os.path.abspath(filepath))
    try:
        res = subprocess.run(
            ['git', 'diff', '-U0', '--no-color', 'HEAD', '--', basename],
            cwd=dirname, capture_output=True, text=True, timeout=5
        )
        if res.returncode != 0:
            return {}
        diff_text = res.stdout
    except Exception:
        return {}

    changes = {} # line_num -> '+' | '~' | '_'
    for line in diff_text.splitlines():
        if line.startswith('@@'):
            m = re.search(r'@@ -(\d+)(?:,(\d+))? \+(\d+)(?:,(\d+))? @@', line)
            if m:
                old_start = int(m.group(1))
                old_count = int(m.group(2)) if m.group(2) else 1
                new_start = int(m.group(3))
                new_count = int(m.group(4)) if m.group(4) else 1

                if old_count == 0 and new_count > 0:
                    for l in range(new_start, new_start + new_count):
                        changes[l] = '+'
                elif new_count == 0 and old_count > 0:
                    line_idx = max(1, new_start)
                    changes[line_idx] = '_'
                else:
                    for l in range(new_start, new_start + new_count):
                        changes[l] = '~'
    return changes

def convert_nonprintable(text, notation='unicode', tabs_width=4):
    res = []
    col = 0
    for char in text:
        if char == ' ':
            res.append('·')
            col += 1
        elif char == '\t':
            # Tab expansion
            if tabs_width <= 0:
                width = 4
            else:
                width = tabs_width - (col % tabs_width)
                if width == 0:
                    width = tabs_width

            if width == 1:
                res.append('↹')
            elif width == 2:
                res.append('├┤')
            else:
                res.append('├' + '─' * (width - 2) + '┤')
            col += width
        elif char == '\n':
            if notation == 'caret':
                res.append('^J\n')
            else:
                res.append('␊\n')
            col = 0
        elif char == '\r':
            if notation == 'caret':
                res.append('^M')
            else:
                res.append('␍')
        elif ord(char) < 32 or ord(char) == 127:
            if notation == 'caret':
                if char == '\0':
                    res.append('^@')
                elif ord(char) == 127:
                    res.append('^?')
                else:
                    res.append('^' + chr(ord(char) + 64))
            else:
                if char == '\0':
                    res.append('␀')
                elif ord(char) == 127:
                    res.append('␡')
                else:
                    res.append(chr(0x2400 + ord(char)))
        else:
            res.append(char)
            col += 1
    return "".join(res)

def print_error(msg, use_color=True):
    prefix = "\x1b[31m[bat error]\x1b[0m" if use_color else "[bat error]"
    sys.stderr.write(f"{prefix}: {msg}\n")

def main():
    raw_args = sys.argv[1:]

    # Check --no-config
    use_config = '--no-config' not in raw_args
    config_args = []
    if use_config:
        cfg_path = get_config_file_path()
        config_args = load_config_args(cfg_path)

    full_args = config_args + raw_args

    # Check for cache subcommand
    non_opt_args = [a for a in full_args if not a.startswith('-')]
    if full_args and full_args[0] == 'cache':
        cache_args = full_args[1:]
        if '--help' in cache_args or '-h' in cache_args:
            sys.stdout.write(CACHE_HELP)
            sys.exit(0)
        elif '--clear' in cache_args or '-c' in cache_args:
            cache_dir = get_cache_dir_path()
            themes_bin = os.path.join(cache_dir, 'themes.bin')
            syntaxes_bin = os.path.join(cache_dir, 'syntaxes.bin')
            metadata_yaml = os.path.join(cache_dir, 'metadata.yaml')

            t_status = "okay" if os.path.exists(themes_bin) else "skipped (not present)"
            s_status = "okay" if os.path.exists(syntaxes_bin) else "skipped (not present)"
            m_status = "okay" if os.path.exists(metadata_yaml) else "skipped (not present)"

            if os.path.exists(themes_bin): os.remove(themes_bin)
            if os.path.exists(syntaxes_bin): os.remove(syntaxes_bin)
            if os.path.exists(metadata_yaml): os.remove(metadata_yaml)

            sys.stdout.write(f"Clearing theme set cache ... {t_status}\nClearing syntax set cache ... {s_status}\nClearing metadata file ... {m_status}\n")
            sys.exit(0)
        elif '--build' in cache_args or '-b' in cache_args:
            cache_dir = get_cache_dir_path()
            cfg_dir = get_config_dir_path()
            os.makedirs(cache_dir, exist_ok=True)

            sys.stdout.write(f"No themes were found in '{cfg_dir}/themes', using the default set\nNo syntaxes were found in '{cfg_dir}/syntaxes', using the default set.\n")
            sys.stdout.write(f"Writing theme set to {cache_dir}/themes.bin ... okay\n")
            sys.stdout.write(f"Writing syntax set to {cache_dir}/syntaxes.bin ... okay\n")
            sys.stdout.write(f"Writing metadata to folder {cache_dir} ... okay\n")
            sys.exit(0)
        else:
            sys.stdout.write(CACHE_HELP)
            sys.exit(0)

    # Manual CLI option parsing to support clap features
    files = []
    show_all = False
    nonprintable_notation = 'unicode'
    binary_behavior = 'no-printing'
    language = None
    fallback_syntax = None
    highlight_lines = []
    custom_filename = None
    diff_mode = False
    diff_context = 2
    tabs = 4
    wrap_mode = 'auto'
    terminal_width_spec = None
    color_when = 'auto'
    italic_text = 'never'
    decorations_when = 'auto'
    paging_when = 'auto'
    pager_cmd = None
    syntax_maps = []
    theme = None
    theme_dark = None
    theme_light = None
    squeeze_blank = False
    squeeze_limit = 1
    strip_ansi_when = 'auto'
    style_list = list(DEFAULT_STYLES)
    line_ranges = []
    unbuffered = False
    quiet_empty = False
    set_terminal_title = False

    i = 0
    while i < len(full_args):
        arg = full_args[i]
        if arg == '--':
            files.extend(full_args[i+1:])
            break
        elif arg == '-V' or arg == '--version':
            sys.stdout.write(VERSION_STRING)
            sys.exit(0)
        elif arg == '-h':
            sys.stdout.write(SHORT_HELP)
            sys.exit(0)
        elif arg == '--help':
            sys.stdout.write(LONG_HELP)
            sys.exit(0)
        elif arg == '--config-file':
            sys.stdout.write(get_config_file_path() + '\n')
            sys.exit(0)
        elif arg == '--config-dir':
            sys.stdout.write(get_config_dir_path() + '\n')
            sys.exit(0)
        elif arg == '--cache-dir':
            sys.stdout.write(get_cache_dir_path() + '\n')
            sys.exit(0)
        elif arg == '--list-languages' or arg == '-L':
