                    style_list = parse_style_arg('plain', style_list)
                elif char == 'n':
                    style_list = parse_style_arg('numbers', style_list)
                elif char == 'A':
                    show_all = True
                elif char == 'd':
                    diff_mode = True
                    if 'changes' not in style_list: style_list.append('changes')
                elif char == 'f':
                    color_when = 'always'
                    decorations_when = 'always'
                elif char == 'S':
                    wrap_mode = 'never'
                elif char == 's':
                    squeeze_blank = True
                elif char == 'u':
                    unbuffered = True
                elif char == 'E':
                    quiet_empty = True
                elif char == 'P':
                    paging_when = 'never'
                elif char == 'h':
                    sys.stdout.write(SHORT_HELP)
