def parse_line_range_spec(spec):
    # Parses specs like 30:40, :40, 40:, 40, -10:, 30:+10, 35::5, 30:40:2
    spec = spec.strip()
    if spec.startswith('-') and spec.endswith(':'):
        # -N: (last N lines)
        try:
            n = int(spec[:-1])
            return ('last', abs(n))
        except ValueError:
            pass
    parts = spec.split(':')
