            if tabs_width <= 0:
                width = 4
            else:
                width = tabs_width - (col % tabs_width)
                if width == 0:
                    width = tabs_width

            if width == 1:
                res.append('↹')
            elif width == 2:
                res.append('├┤')
            else:
                res.append('├' + '─' * (width - 2) + '┤')
            col += width
        elif char == '\n':
            if notation == 'caret':
                res.append('^J\n')
            else:
                res.append('␊\n')
            col = 0
        elif char == '\r':
            if notation == 'caret':
                res.append('^M')
            else:
                res.append('␍')
        elif ord(char) < 32 or ord(char) == 127:
            if notation == 'caret':
                if char == '\0':
                    res.append('^@')
                elif ord(char) == 127:
                    res.append('^?')
