    # Manual CLI option parsing to support clap features
    files = []
    show_all = False
    nonprintable_notation = 'unicode'
    binary_behavior = 'no-printing'
    language = None
    fallback_syntax = None
    highlight_lines = []
    custom_filename = None
    diff_mode = False
