        except ValueError:
            pass
    parts = spec.split(':')
    if len(parts) == 1:
        try:
            val = int(parts[0])
            return (val, val)
        except ValueError:
            return (1, sys.maxsize)
    elif len(parts) == 2:
        p1, p2 = parts[0], parts[1]
        start = int(p1) if p1 else 1
        if p2.startswith('+'):
            end = start + int(p2[1:])
        else:
            end = int(p2) if p2 else sys.maxsize
        return (start, end)
    elif len(parts) == 3:
        p1, p2, p3 = parts[0], parts[1], parts[2]
        if p1 and p2 == '' and p3:
            center = int(p1)
            ctx = int(p3)
            return (max(1, center - ctx), center + ctx)
        elif p1 and p2 and p3:
            start = int(p1)
            end = int(p2)
