    color_when = 'auto'
    italic_text = 'never'
    decorations_when = 'auto'
    paging_when = 'auto'
    pager_cmd = None
    syntax_maps = []
    theme = None
    theme_dark = None
    theme_light = None
    squeeze_blank = False
    squeeze_limit = 1
    strip_ansi_when = 'auto'
    style_list = list(DEFAULT_STYLES)
    line_ranges = []
    unbuffered = False
    quiet_empty = False
    set_terminal_title = False
    explicit_decorations = False

    i = 0
    while i < len(full_args):
        arg = full_args[i]
        if arg == '--':
            files.extend(full_args[i+1:])
            break
