    changes = {}
    for line in diff_text.splitlines():
        if line.startswith('@@'):
            m = re.search(r'@@ -(\d+)(?:,(\d+))? \+(\d+)(?:,(\d+))? @@', line)
            if m:
                old_start = int(m.group(1))
                old_count = int(m.group(2)) if m.group(2) else 1
                new_start = int(m.group(3))
                new_count = int(m.group(4)) if m.group(4) else 1

                if old_count == 0 and new_count > 0:
                    for l in range(new_start, new_start + new_count):
                        changes[l] = '+'
                elif new_count == 0 and old_count > 0:
                    line_idx = max(1, new_start)
                    changes[line_idx] = '_'
                else:
                    for l in range(new_start, new_start + new_count):
                        changes[l] = '~'
    return changes

def convert_nonprintable(text, notation='unicode', tabs_width=4):
    res = []
    col = 0
    for char in text:
        if char == ' ':
            res.append('·')
            col += 1
        elif char == '\t':
            if tabs_width <= 0:
                width = 4
            else:
                width = tabs_width - (col % tabs_width)
                if width == 0:
                    width = tabs_width

            if width == 1:
                res.append('↹')
            elif width == 2:
                res.append('├┤')
            else:
                res.append('├' + '─' * (width - 2) + '┤')
            col += width
        elif char == '\n':
            if notation == 'caret':
                res.append('^J\n')
            else:
                res.append('␊\n')
            col = 0
        elif char == '\r':
            if notation == 'caret':
                res.append('^M')
            else:
                res.append('␍')
        elif ord(char) < 32 or ord(char) == 127:
            if notation == 'caret':
                if char == '\0':
                    res.append('^@')
                elif ord(char) == 127:
                    res.append('^?')
                else:
                    res.append('^' + chr(ord(char) + 64))
            else:
                if char == '\0':
                    res.append('␀')
                elif ord(char) == 127:
                    res.append('␡')
                else:
                    res.append(chr(0x2400 + ord(char)))
        else:
            res.append(char)
            col += 1

    return "".join(res)

