class BatMonokaiFormatter(Formatter):
    def format(self, tokensource, outfile):
        for ttype, value in tokensource:
            if not value:
                continue
            if value == '\n':
                outfile.write('\n')
                continue
            if ttype in Token.Keyword:
                code = '38;5;203'
            elif ttype in Token.Name.Function or ttype in Token.Name.Class:
