                if width == 0:
                    width = tabs_width

            if width == 1:
                res.append('↹')
            elif width == 2:
                res.append('├┤')
            else:
                res.append('├' + '─' * (width - 2) + '┤')
            col += width
        elif char == '\n':
            if notation == 'caret':
                res.append('^J\n')
            else:
                res.append('␊\n')
            col = 0
        elif char == '\r':
            if notation == 'caret':
                res.append('^M')
            else:
                res.append('␍')
        elif ord(char) < 32 or ord(char) == 127:
            if notation == 'caret':
                if char == '\0':
                    res.append('^@')
                elif ord(char) == 127:
                    res.append('^?')
                else:
                    res.append('^' + chr(ord(char) + 64))
            else:
                if char == '\0':
                    res.append('␀')
                elif ord(char) == 127:
                    res.append('␡')
                else:
                    res.append(chr(0x2400 + ord(char)))
        else:
            res.append(char)
            col += 1

    return "".join(res)

def print_error(msg):
    sys.stderr.write(f"\x1b[31m[bat error]\x1b[0m: {msg}\n")

