        elif arg == '-A' or arg == '--show-all':
            show_all = True
        elif arg.startswith('--nonprintable-notation='):
            nonprintable_notation = arg.split('=', 1)[1]
        elif arg.startswith('--binary='):
            binary_behavior = arg.split('=', 1)[1]
        elif arg == '-p' or arg == '--plain':
            style_list = parse_style_arg('plain', style_list)
        elif arg == '-pp':
            style_list = parse_style_arg('plain', style_list)
            paging_when = 'never'
        elif arg == '-n' or arg == '--number':
            style_list = parse_style_arg('numbers', style_list)
            explicit_decorations = True
        elif arg.startswith('-l=') or arg.startswith('--language='):
            language = arg.split('=', 1)[1]
        elif arg == '-l' or arg == '--language':
            i += 1
            if i < len(full_args): language = full_args[i]
        elif arg.startswith('--fallback-syntax=') or arg.startswith('--fallback-language='):
            fallback_syntax = arg.split('=', 1)[1]
        elif arg == '--fallback-syntax' or arg == '--fallback-language':
            i += 1
            if i < len(full_args): fallback_syntax = full_args[i]
        elif arg.startswith('-H=') or arg.startswith('--highlight-line='):
            highlight_lines.append(parse_line_range_spec(arg.split('=', 1)[1]))
        elif arg == '-H' or arg == '--highlight-line':
            i += 1
            if i < len(full_args): highlight_lines.append(parse_line_range_spec(full_args[i]))
        elif arg.startswith('--file-name='):
            custom_filename = arg.split('=', 1)[1]
        elif arg == '--file-name':
            i += 1
            if i < len(full_args): custom_filename = full_args[i]
        elif arg == '-d' or arg == '--diff':
            diff_mode = True
            if 'changes' not in style_list:
                style_list.append('changes')
        elif arg.startswith('--diff-context='):
            diff_context = int(arg.split('=', 1)[1])
        elif arg == '--diff-context':
            i += 1
            if i < len(full_args): diff_context = int(full_args[i])
        elif arg.startswith('--tabs='):
            tabs = int(arg.split('=', 1)[1])
        elif arg == '--tabs':
            i += 1
            if i < len(full_args): tabs = int(full_args[i])
        elif arg.startswith('--wrap='):
            wrap_mode = arg.split('=', 1)[1]
        elif arg == '--wrap':
            i += 1
            if i < len(full_args): wrap_mode = full_args[i]
        elif arg == '-S' or arg == '--chop-long-lines':
            wrap_mode = 'never'
        elif arg.startswith('--terminal-width='):
            terminal_width_spec = arg.split('=', 1)[1]
        elif arg == '--terminal-width':
            i += 1
            if i < len(full_args): terminal_width_spec = full_args[i]
        elif arg.startswith('--color='):
            color_when = arg.split('=', 1)[1]
        elif arg == '--color':
            i += 1
            if i < len(full_args): color_when = full_args[i]
        elif arg.startswith('--italic-text='):
            italic_text = arg.split('=', 1)[1]
        elif arg.startswith('--decorations='):
            decorations_when = arg.split('=', 1)[1]
        elif arg == '-f' or arg == '--force-colorization':
            color_when = 'always'
            decorations_when = 'always'
            explicit_decorations = True
        elif arg.startswith('--paging='):
            paging_when = arg.split('=', 1)[1]
        elif arg == '-P' or arg == '--no-paging':
            paging_when = 'never'
        elif arg.startswith('--pager='):
            pager_cmd = arg.split('=', 1)[1]
        elif arg.startswith('-m=') or arg.startswith('--map-syntax='):
            syntax_maps.append(arg.split('=', 1)[1])
        elif arg == '-m' or arg == '--map-syntax':
            i += 1
            if i < len(full_args): syntax_maps.append(full_args[i])
        elif arg.startswith('--theme='):
            theme = arg.split('=', 1)[1]
        elif arg == '--theme':
            i += 1
            if i < len(full_args): theme = full_args[i]
        elif arg == '-s' or arg == '--squeeze-blank':
            squeeze_blank = True
        elif arg.startswith('--squeeze-limit='):
            squeeze_limit = int(arg.split('=', 1)[1])
            squeeze_blank = True
        elif arg.startswith('--strip-ansi='):
            strip_ansi_when = arg.split('=', 1)[1]
        elif arg.startswith('--style='):
            style_list = parse_style_arg(arg.split('=', 1)[1], style_list)
        elif arg == '--style':
            i += 1
            if i < len(full_args): style_list = parse_style_arg(full_args[i], style_list)
        elif arg.startswith('-r=') or arg.startswith('--line-range='):
            line_ranges.append(parse_line_range_spec(arg.split('=', 1)[1]))
        elif arg == '-r' or arg == '--line-range':
            i += 1
            if i < len(full_args): line_ranges.append(parse_line_range_spec(full_args[i]))
        elif arg == '-u' or arg == '--unbuffered':
            unbuffered = True
        elif arg == '-E' or arg == '--quiet-empty':
            quiet_empty = True
        elif arg == '--set-terminal-title':
            set_terminal_title = True
        elif arg.startswith('-') and len(arg) > 1 and not arg.startswith('--'):
            for char in arg[1:]:
                if char == 'p':
                    style_list = parse_style_arg('plain', style_list)
                elif char == 'n':
                    style_list = parse_style_arg('numbers', style_list)
                    explicit_decorations = True
                elif char == 'A':
                    show_all = True
                elif char == 'd':
                    diff_mode = True
                    if 'changes' not in style_list: style_list.append('changes')
                elif char == 'f':
                    color_when = 'always'
                    decorations_when = 'always'
                    explicit_decorations = True
                elif char == 'S':
                    wrap_mode = 'never'
                elif char == 's':
                    squeeze_blank = True
                elif char == 'u':
                    unbuffered = True
                elif char == 'E':
                    quiet_empty = True
                elif char == 'P':
                    paging_when = 'never'
                elif char == 'h':
                    sys.stdout.write(SHORT_HELP)
                    sys.exit(0)
                elif char == 'V':
                    sys.stdout.write(VERSION_STRING)
                    sys.exit(0)
                elif char == 'L':
                    sys.stdout.write(LANGUAGES_LIST)
                    sys.exit(0)
        elif arg == '-' or not arg.startswith('-'):
            files.append(arg)
        i += 1

    if not files:
        files = ['-']

    # Terminal TTY check
    is_tty = sys.stdout.isatty()

    if color_when == 'always':
        use_color = True
    elif color_when == 'never':
        use_color = False
    else:
        use_color = is_tty

    if decorations_when == 'always' or explicit_decorations:
        use_decorations = True
    elif decorations_when == 'never':
        use_decorations = False
    else:
        use_decorations = is_tty

    if not use_decorations:
        active_styles = []
    else:
        active_styles = list(style_list)

    if unbuffered:
        if 'numbers' in active_styles:
            active_styles.remove('numbers')

    term_width = 80
    if is_tty:
        term_width = shutil.get_terminal_size().columns
    if 'BAT_WIDTH' in os.environ:
        try: term_width = int(os.environ['BAT_WIDTH'])
        except ValueError: pass

    if terminal_width_spec:
        if terminal_width_spec.startswith('+'):
            term_width += int(terminal_width_spec[1:])
        elif terminal_width_spec.startswith('-'):
            term_width -= int(terminal_width_spec[1:])
        else:
            term_width = int(terminal_width_spec)

    had_error = False
    output_chunks = []

    for f_idx, file_path in enumerate(files):
        display_name = custom_filename if custom_filename else (file_path if file_path != '-' else 'STDIN')
        is_stdin = (file_path == '-')

        content_bytes = b''
        file_size_bytes = 0

        if is_stdin:
            try:
                content_bytes = sys.stdin.buffer.read()
            except Exception as e:
                print_error(f"stdin: {e}")
                had_error = True
                continue
        else:
            try:
                file_size_bytes = os.path.getsize(file_path)
                with open(file_path, 'rb') as f:
                    content_bytes = f.read()
            except Exception:
                print_error(f"'{file_path}': No such file or directory (os error 2)")
                had_error = True
                continue

        # Check binary file
        is_binary = b'\x00' in content_bytes[:1024]
        if is_binary and binary_behavior == 'no-printing' and not show_all and ('grid' in active_styles or 'header-filename' in active_styles):
            header_lines = []
            if 'grid' in active_styles:
                side_w = 5
                header_lines.append(f"\x1b[38;5;246m{'─'*side_w}┬{'─'*(term_width-side_w-1)}\x1b[0m")
                disp = f"File: \x1b[1m{display_name}\x1b[0m" if not is_stdin or custom_filename else "\x1b[1mSTDIN\x1b[0m"
                header_lines.append(f"     \x1b[38;5;246m│ \x1b[0m{disp}   <BINARY>")
                header_lines.append(f"\x1b[38;5;246m{'─'*side_w}┴{'─'*(term_width-side_w-1)}\x1b[0m\n")
            output_chunks.append("\n".join(header_lines))
            continue

        text = content_bytes.decode('utf-8', errors='replace')

        # Check empty
        if not text:
            if quiet_empty:
                continue
            if 'grid' in active_styles or 'header-filename' in active_styles:
                side_w = 5
                header_lines = []
                if 'grid' in active_styles:
                    header_lines.append(f"\x1b[38;5;246m{'─'*side_w}┬{'─'*(term_width-side_w-1)}\x1b[0m")
                    disp = f"File: \x1b[1m{display_name}\x1b[0m" if not is_stdin or custom_filename else "\x1b[1mSTDIN\x1b[0m"
                    header_lines.append(f"     \x1b[38;5;246m│ \x1b[0m{disp}   <EMPTY>")
                    if 'header-filesize' in active_styles:
                        fs_str = format_file_size(file_size_bytes) if not is_stdin else "-"
                        header_lines.append(f"     \x1b[38;5;246m│ \x1b[0mSize: \x1b[1m{fs_str}\x1b[0m")
                    header_lines.append(f"\x1b[38;5;246m{'─'*side_w}┴{'─'*(term_width-side_w-1)}\x1b[0m\n")
                elif 'header-filename' in active_styles:
                    disp = f"File: \x1b[1m{display_name}\x1b[0m" if not is_stdin or custom_filename else "\x1b[1mSTDIN\x1b[0m"
                    header_lines.append(f"{disp}   <EMPTY>\n")
                output_chunks.append("\n".join(header_lines))
                continue

        # Strip ANSI if needed
        if strip_ansi_when == 'always' or (strip_ansi_when == 'auto' and language != 'plain'):
            text = re.sub(r'\x1b\[[0-9;]*[mK]', '', text)

        lines = text.split('\n')

        # Git changes
        git_changes = {}
        if ('changes' in active_styles or diff_mode) and not is_stdin:
            git_changes = get_git_changes(file_path)

        # Line range filtering
        selected_lines = set()
        total_lines = len(lines)

        if line_ranges:
            for r in line_ranges:
                if r[0] == 'last':
                    cnt = r[1]
                    start = max(1, total_lines - cnt + 1)
                    end = total_lines
                else:
                    start = max(1, r[0])
                    end = min(total_lines, r[1])
                for idx in range(start, end + 1):
                    selected_lines.add(idx)
        elif diff_mode:
            if git_changes:
                for mod_line in git_changes.keys():
                    start = max(1, mod_line - diff_context)
                    end = min(total_lines, mod_line + diff_context)
                    for idx in range(start, end + 1):
                        selected_lines.add(idx)
            else:
                selected_lines = set()
        else:
            selected_lines = set(range(1, total_lines + 1))

        # Check map syntax
        lang_name = language
        if not lang_name and syntax_maps:
            test_fn = display_name if display_name else file_path
            for sm in syntax_maps:
                if ':' in sm:
                    pat, syn = sm.split(':', 1)
                    if fnmatch.fnmatch(test_fn, pat) or fnmatch.fnmatch(os.path.basename(test_fn), pat):
                        lang_name = syn
                        break

        # Determine syntax lexer
        lexer = None
        if not lang_name and custom_filename:
            try: lexer = get_lexer_for_filename(custom_filename)
            except ClassNotFound: pass

        if not lang_name and not lexer and not is_stdin:
            try: lexer = get_lexer_for_filename(file_path)
            except ClassNotFound: pass

        if not lang_name and not lexer and fallback_syntax:
            lang_name = fallback_syntax

        if lang_name:
            try: lexer = get_lexer_by_name(lang_name.lower())
            except ClassNotFound: pass

        # Syntax highlight lines
        highlighted_lines = []
        if use_color and lexer:
            try:
                buf = io.StringIO()
                BatMonokaiFormatter().format(lexer.get_tokens(text), buf)
                hl_text = buf.getvalue()
                highlighted_lines = hl_text.split('\n')
            except Exception:
                highlighted_lines = [f"\x1b[38;5;231m{l}\x1b[0m" if l else "" for l in lines]
        elif use_color:
            highlighted_lines = [f"\x1b[38;5;231m{l}\x1b[0m" if l else "" for l in lines]
        else:
            highlighted_lines = lines

        while len(highlighted_lines) < len(lines):
            highlighted_lines.append("")

        # Formatting layout calculation
        max_num = total_lines
        num_w = max(4, len(str(max_num))) if 'numbers' in active_styles else 0

        has_changes = ('changes' in active_styles) and (bool(git_changes) or diff_mode)
        changes_w = 2 if has_changes else 0

        sidebar_w = num_w + changes_w + (1 if 'numbers' in active_styles or has_changes else 0)

        # Header output
        res_text = []

        if f_idx > 0 and 'rule' in active_styles and not ('grid' in active_styles):
            res_text.append(f"\x1b[38;5;246m{'─'*term_width}\x1b[0m")

        has_header_content = ('header-filename' in active_styles) or ('header-filesize' in active_styles)

        if 'grid' in active_styles:
            grid_color = "\x1b[38;5;246m" if use_color else ""
            reset_c = "\x1b[0m" if use_color else ""
            bold_c = "\x1b[1m" if use_color else ""

            if has_header_content:
                if sidebar_w > 0:
                    res_text.append(f"{grid_color}{'─'*sidebar_w}┬{'─'*(term_width-sidebar_w-1)}{reset_c}")
                else:
                    res_text.append(f"{grid_color}{'─'*term_width}{reset_c}")

                if 'header-filename' in active_styles:
                    disp = f"File: {bold_c}{display_name}{reset_c}" if not is_stdin or custom_filename else f"{bold_c}STDIN{reset_c}"
                    if sidebar_w > 0:
                        res_text.append(f" {' '*max(0, sidebar_w-1)}{grid_color}│ {reset_c}{disp}")
                    else:
                        res_text.append(disp)

                if 'header-filesize' in active_styles:
                    fs_str = format_file_size(file_size_bytes) if not is_stdin else "-"
                    if sidebar_w > 0:
                        res_text.append(f" {' '*max(0, sidebar_w-1)}{grid_color}│ {reset_c}Size: {bold_c}{fs_str}{reset_c}")
                    else:
                        res_text.append(f"Size: {bold_c}{fs_str}{reset_c}")

                if sidebar_w > 0:
                    res_text.append(f"{grid_color}{'─'*sidebar_w}┼{'─'*(term_width-sidebar_w-1)}{reset_c}")
                else:
                    res_text.append(f"{grid_color}{'─'*term_width}{reset_c}")
            else:
                if sidebar_w > 0:
                    res_text.append(f"{grid_color}{'─'*sidebar_w}┬{'─'*(term_width-sidebar_w-1)}{reset_c}")
                else:
                    res_text.append(f"{grid_color}{'─'*term_width}{reset_c}")

        elif 'header-filename' in active_styles:
            bold_c = "\x1b[1m" if use_color else ""
            reset_c = "\x1b[0m" if use_color else ""
            disp = f"File: {bold_c}{display_name}{reset_c}" if not is_stdin or custom_filename else f"{bold_c}STDIN{reset_c}"
            res_text.append(disp)
            if 'header-filesize' in active_styles:
                fs_str = format_file_size(file_size_bytes) if not is_stdin else "-"
                res_text.append(f"Size: {bold_c}{fs_str}{reset_c}")

        # Content rendering
        sorted_line_indices = sorted(list(selected_lines))
        prev_idx = None
        blank_count = 0

        for line_num in sorted_line_indices:
            idx = line_num - 1
            if idx >= len(lines):
                break

            raw_line = lines[idx]

            # Squeeze blank lines handling
            if squeeze_blank:
                if not raw_line.strip():
                    blank_count += 1
                    if blank_count > squeeze_limit:
                        continue
                else:
                    blank_count = 0

            # Snip marker is drawn when line range skips lines
            if prev_idx is not None and idx > prev_idx + 1 and 'snip' in active_styles and not squeeze_blank:
                snip_color = "\x1b[38;5;246m" if use_color else ""
                snip_reset = "\x1b[0m" if use_color else ""
                snip_line = f"{snip_color} ... │ ─ ─ ─ ─ ─ ─ ─ ─ ─ ─ ─ ─ ─ ─ ─ ─ ─ ─ 8< ─ ─ ─ ─ ─ ─ ─ ─ ─ ─ ─ ─ ─ ─ ─ ─ ─{snip_reset}"
                res_text.append(snip_line)

            prev_idx = idx

            hl_line = highlighted_lines[idx]

            if show_all:
                hl_line = convert_nonprintable(raw_line, nonprintable_notation, tabs)

            is_highlighted = False
            for hl_r in highlight_lines:
                if hl_r[0] <= line_num <= hl_r[1]:
                    is_highlighted = True
                    break

            side_parts = []
            if 'numbers' in active_styles:
                num_str = f"{line_num:>{num_w}}"
                num_col = f"\x1b[38;5;246m{num_str}\x1b[0m" if use_color else num_str
                side_parts.append(num_col)

            if has_changes:
                ch = git_changes.get(line_num, ' ')
                if ch == '+':
                    ch_str = "\x1b[32m+\x1b[0m" if use_color else "+"
                elif ch == '~':
                    ch_str = "\x1b[33m~\x1b[0m" if use_color else "~"
                elif ch == '_':
                    ch_str = "\x1b[31m_\x1b[0m" if use_color else "_"
                else:
                    ch_str = " "
                side_parts.append(ch_str)

            sidebar_str = " ".join(side_parts) if side_parts else ""

            if 'grid' in active_styles:
                grid_bar = "\x1b[38;5;246m│\x1b[0m" if use_color else "│"
                if sidebar_str:
                    prefix = f"{sidebar_str} {grid_bar} "
                else:
                    prefix = ""
            elif sidebar_str:
                prefix = f"{sidebar_str} "
            else:
                prefix = ""

            if is_highlighted and use_color:
                bg_code = "\x1b[48;5;236"
                content_w = max(0, term_width - sidebar_w - 2)
                clean_l = re.sub(r'\x1b\[[0-9;]*m', '', hl_line)
                pad_w = max(0, content_w - len(clean_l))
                hl_line = f"{bg_code};38;5;231m{clean_l}\x1b[0m{bg_code}m{' '*pad_w}\x1b[0m"

            res_text.append(f"{prefix}{hl_line}")

        if 'grid' in active_styles and sorted_line_indices:
            grid_color = "\x1b[38;5;246m" if use_color else ""
            reset_c = "\x1b[0m" if use_color else ""
            if sidebar_w > 0:
                res_text.append(f"{grid_color}{'─'*sidebar_w}┴{'─'*(term_width-sidebar_w-1)}{reset_c}")
            else:
                res_text.append(f"{grid_color}{'─'*term_width}{reset_c}")

        output_chunks.append("\n".join(res_text) + "\n")

    final_output = "".join(output_chunks)

    if paging_when == 'never':
        sys.stdout.write(final_output)
    else:
        use_pager = (paging_when == 'always') or (paging_when == 'auto' and is_tty and final_output.count('\n') > shutil.get_terminal_size().lines)
        if use_pager:
            pager = pager_cmd or os.environ.get('BAT_PAGER') or os.environ.get('PAGER') or 'less -RF'
            try:
                proc = subprocess.Popen(pager, shell=True, stdin=subprocess.PIPE, text=True)
                proc.communicate(input=final_output)
            except Exception:
                sys.stdout.write(final_output)
        else:
            sys.stdout.write(final_output)

    if had_error:
        sys.exit(1)
    else:
        sys.exit(0)

if __name__ == '__main__':
    main()
